USE [Hyperyek]; IF OBJECT_ID(N'dbo.vw_IntegrationDashboard',N'V') IS NOT NULL DROP VIEW dbo.vw_IntegrationDashboard; EXEC('CREATE VIEW dbo.vw_IntegrationDashboard AS SELECT c.ShopId,c.TenantId,c.Provider,c.DisplayName,c.IsEnabled,c.LastSyncAtUtc,COUNT(m.Id) AS MappingCount,MAX(r.FinishedAtUtc) AS LastRunAtUtc,SUM(CASE WHEN r.Status=2 THEN 1 ELSE 0 END) AS FailedRuns FROM dbo.ExternalIntegrationConnections c LEFT JOIN dbo.ExternalProductMappings m ON m.ConnectionId=c.Id LEFT JOIN dbo.IntegrationSyncRuns r ON r.ConnectionId=c.Id GROUP BY c.ShopId,c.TenantId,c.Provider,c.DisplayName,c.IsEnabled,c.LastSyncAtUtc');
